+    const { content, root, scroller } = createReverseScroller();
+    scroller.scrollTop = -420;
+
+    expect(scrollReverseMessageList(root, content, 120, 0)).toBe(true);
+    expect(scroller.scrollTop).toBe(-300);
+  });
+
