+// @vitest-environment jsdom
+import { fireEvent, render, screen } from "@testing-library/react";
+import { describe, expect, it, vi } from "vitest";
+import AgentScopeRuntimeResponseBuilder from "../../../node_modules/@agentscope-ai/chat/lib/AgentScopeRuntimeWebUI/core/AgentScopeRuntime/Response/Builder.js";
+
+vi.mock("react-i18next", () => ({
+  useTranslation: () => ({
+    t: (key: string) =>
+      ({
+        "files.artifactCreated": "已新增",
+        "files.artifactModified": "已修改",
+        "files.artifactsCollapse": "收起",
+        "files.artifactsExpand": "展开更多",
+      })[key] ?? key,
+  }),
+}));
+
+import ResponseArtifactList from "./ResponseArtifactList";
+
+function successfulFileIo(path: string, name = "write_file") {
+  return [
+    {
+      id: `result-${path}`,
+      type: "tool_call_output",
+      status: "completed",
+      content: [
+        {
+          data: {
+            call_id: `call-${path}`,
+            name,
+            arguments: JSON.stringify({ file_path: path }),
+          },
+        },
+        { data: { call_id: `call-${path}`, state: "success" } },
+      ],
+    },
+  ];
+}
+
+describe("ResponseArtifactList", () => {
+  it("renders each file as a flat preview entry", () => {
+    render(
+      <ResponseArtifactList
+        messages={[
+          ...successfulFileIo("snack-shop/public/main.js"),
+          ...successfulFileIo("snack-shop/package.json"),
+        ]}
+      />,
+    );
+
+    expect(screen.getByText("main.js")).toBeInTheDocument();
+    expect(screen.getByText("snack-shop/public/main.js")).toBeInTheDocument();
+    expect(screen.getByText("package.json")).toBeInTheDocument();
+    expect(screen.getAllByText("已新增")).toHaveLength(2);
+  });
+
+  it("marks edit and append operations as modified", () => {
+    render(
+      <ResponseArtifactList
+        messages={[
+          ...successfulFileIo("notes.md", "edit_file"),
+          ...successfulFileIo("journal.md", "append_file"),
+        ]}
+      />,
+    );
+
+    expect(screen.getAllByText("已修改")).toHaveLength(2);
+  });
+
+  it("collapses files beyond two rows and allows expanding them", () => {
+    render(
+      <ResponseArtifactList
+        messages={Array.from({ length: 3 }, (_, index) =>
+          successfulFileIo(`file-${index}.md`),
+        ).flat()}
+      />,
+    );
+
+    const toggle = screen.getByRole("button", { name: /展开更多/ });
+    expect(toggle).toHaveAttribute("aria-expanded", "false");
+    fireEvent.click(toggle);
+    expect(toggle).toHaveAttribute("aria-expanded", "true");
+    expect(screen.getByText("收起")).toBeInTheDocument();
+  });
+
+  it("shows two columns when the response has enough width", () => {
+    const rect = vi
+      .spyOn(HTMLElement.prototype, "getBoundingClientRect")
+      .mockReturnValue({ width: 700 } as DOMRect);
+    render(
+      <ResponseArtifactList
+        messages={Array.from({ length: 5 }, (_, index) =>
+          successfulFileIo(`wide-${index}.md`),
+        ).flat()}
+      />,
+    );
+
+    expect(
+      screen.queryByRole("button", { name: "wide-0.md wide-0.md" }),
+    ).not.toBeInTheDocument();
+    expect(
+      screen.getByRole("button", { name: /展开更多/ }),
+    ).toBeInTheDocument();
+    rect.mockRestore();
+  });
+
+  it("opens the existing file preview when clicked", () => {
+    const listener = vi.fn();
+    window.addEventListener("qwenpaw:open-file-preview", listener);
+    render(
+      <ResponseArtifactList messages={successfulFileIo("reports/final.md")} />,
+    );
+
+    fireEvent.click(
+      screen.getByRole("button", {
+        name: "final.md reports/final.md",
+      }),
+    );
+
+    const event = listener.mock.calls[0][0] as CustomEvent;
+    expect(event.detail.target).toEqual({
+      source: "workspace",
+      path: "reports/final.md",
+      root: "project",
+    });
+    window.removeEventListener("qwenpaw:open-file-preview", listener);
+  });
+
+  it("renders nothing when the response has no successful file IO", () => {
+    const { container } = render(
+      <ResponseArtifactList
+        messages={[
+          { type: "message", content: [{ text: "hello" }] },
+          {
+            type: "tool_call_output",
+            content: [
+              {
+                data: {
+                  name: "shell",
+                  arguments: JSON.stringify({
+                    file_path: "not-an-artifact.md",
+                  }),
+                },
+              },
+              { data: { state: "success" } },
+            ],
+          },
+        ]}
+      />,
+    );
+
+    expect(container).toBeEmptyDOMElement();
+  });
+
+  it("renders a live SSE file after ResponseCard merges its tool result", () => {
+    const liveOutput = [
+      {
+        id: "write-call",
+        type: "tool_call",
+        content: [
+          {
+            data: {
+              call_id: "write-call",
+              name: "write_file",
+              arguments: JSON.stringify({ file_path: "result.md" }),
+            },
+          },
+        ],
+      },
+      {
+        id: "write-output",
+        type: "tool_call_output",
+        content: [{ data: { call_id: "write-call", state: "success" } }],
+      },
+    ];
+    const messages = AgentScopeRuntimeResponseBuilder.mergeToolMessages(
+      liveOutput as never,
+    );
+
+    render(<ResponseArtifactList messages={messages} />);
+
+    expect(
+      screen.getByRole("button", { name: "result.md result.md" }),
+    ).toBeInTheDocument();
+  });
+
+  it("does not show failed file operations", () => {
+    const { container } = render(
+      <ResponseArtifactList
+        messages={[
+          {
+            type: "tool_call_output",
+            status: "failed",
+            content: [
+              {
+                data: {
+                  call_id: "failed-write",
+                  name: "write_file",
+                  arguments: JSON.stringify({ file_path: "failed.md" }),
+                },
+              },
+              { data: { call_id: "failed-write", state: "failed" } },
+            ],
+          },
+        ]}
+      />,
+    );
+
+    expect(container).toBeEmptyDOMElement();
+  });
+});
diff --git a/console/src/features/files-workspace/ResponseArtifactList.tsx b/console/src/features/files-workspace/ResponseArtifactList.tsx
new file mode 100644
index 00000000000..ba4875b8549
--- /dev/null
+++ b/console/src/features/files-workspace/ResponseArtifactList.tsx
@@ -0,0 +1,266 @@
+import { ChevronDown, ChevronUp } from "lucide-react";
+import { useLayoutEffect, useRef, useState } from "react";
+import { useTranslation } from "react-i18next";
+import { chatApi } from "../../api/modules/chat";
+import FileGlyph from "./FileGlyph";
+import { parseInternalFileLink } from "./internalFileLinks";
+import type { FileTarget } from "./types";
+import styles from "./ResponseArtifactList.module.less";
+
+interface ResponseArtifactListProps {
+  messages: unknown;
+}
+
+type ArtifactChange = "created" | "modified";
+interface ResponseArtifact {
+  id: string;
+  name: string;
+  path: string;
+  target: FileTarget;
+  toolName: string;
+}
+
+const MIN_FILE_WIDTH = 320;
+const GRID_GAP = 8;
+const FILE_IO_TOOLS = new Set(["appendfile", "editfile", "writefile"]);
+const TOOL_OUTPUT_TYPES = new Set([
+  "tool_call_output",
+  "plugin_call_output",
+  "function_call_output",
+  "mcp_call_output",
+  "component_call_output",
+]);
+const FAILED_STATES = new Set([
+  "cancelled",
+  "canceled",
+  "denied",
+  "error",
+  "failed",
+  "interrupted",
+  "rejected",
+]);
+
+function record(value: unknown): Record<string, unknown> | null {
+  return value && typeof value === "object"
+    ? (value as Record<string, unknown>)
+    : null;
+}
+
+function parsedRecord(value: unknown): Record<string, unknown> | null {
+  const direct = record(value);
+  if (direct) return direct;
+  if (typeof value !== "string") return null;
+  try {
+    return record(JSON.parse(value));
+  } catch {
+    return null;
+  }
+}
+
+function firstString(
+  value: Record<string, unknown>,
+  keys: readonly string[],
+): string {
+  for (const key of keys) {
+    const candidate = value[key];
+    if (typeof candidate === "string" && candidate.trim()) {
+      return candidate.trim();
+    }
+  }
+  return "";
+}
+
+function contentData(
+  item: Record<string, unknown>,
+  index: number,
+): Record<string, unknown> {
+  const content = Array.isArray(item.content) ? item.content : [];
+  return record(record(content[index])?.data) ?? {};
+}
+
+function normalizedToolName(name: string): string {
+  return name.replace(/[^a-z\d]/gi, "").toLowerCase();
+}
+
+function targetForPath(path: string): FileTarget | null {
+  const normalized = path.trim().replace(/\\/g, "/");
+  const workspaceTarget = parseInternalFileLink(
+    normalized.replace(/^(?:\.\/)+/, ""),
+  );
+  if (workspaceTarget) return { ...workspaceTarget, root: "project" };
+  if (
+    normalized.startsWith("/") ||
+    normalized.startsWith("~") ||
+    /^[a-z]:\//i.test(normalized)
+  ) {
+    return {
+      source: "attachment",
+      path: normalized,
+      artifactUrl: chatApi.filePreviewUrl(normalized),
+    };
+  }
+  return null;
+}
+
+function extractResponseArtifacts(messages: unknown): ResponseArtifact[] {
+  if (!Array.isArray(messages)) return [];
+
+  const artifacts = new Map<string, ResponseArtifact>();
+  for (const value of messages) {
+    const item = record(value);
+    if (!item) continue;
+    const type = firstString(item, ["type"]);
+    if (!TOOL_OUTPUT_TYPES.has(type)) continue;
+
+    // mergeToolMessages uses [call content, result content] for a completed
+    // tool entry. Reusing that shape keeps artifacts in sync with ResponseTool.
+    const callData = contentData(item, 0);
+    const resultData = contentData(item, 1);
+    const state = (
+      firstString(resultData, ["state", "status"]) ||
+      firstString(item, ["state", "status"])
+    ).toLowerCase();
+    if (
+      resultData.is_error === true ||
+      item.is_error === true ||
+      FAILED_STATES.has(state)
+    ) {
+      continue;
+    }
+
+    const toolName =
+      firstString(callData, ["name"]) || firstString(item, ["name"]);
+    if (!FILE_IO_TOOLS.has(normalizedToolName(toolName))) continue;
+    const params =
+      parsedRecord(callData.arguments) ??
+      parsedRecord(item.params) ??
+      parsedRecord(item.arguments) ??
+      {};
+    const path = firstString(params, ["file_path"]);
+    const target = targetForPath(path);
+    if (!target) continue;
+    const name = path.replace(/\\/g, "/").split("/").pop() || "file";
+    const id = `${target.source}:${target.path}`;
+    artifacts.delete(id);
+    artifacts.set(id, {
+      id,
+      name,
+      path,
+      target,
+      toolName,
+    });
+  }
+  return Array.from(artifacts.values()).reverse();
+}
+
+function artifactChange(toolName?: string): ArtifactChange {
+  const normalized = normalizedToolName(toolName ?? "");
+  return normalized === "writefile" ? "created" : "modified";
+}
+
+export default function ResponseArtifactList({
+  messages,
+}: ResponseArtifactListProps) {
+  const { t } = useTranslation();
+  const artifacts = extractResponseArtifacts(messages);
+  const gridRef = useRef<HTMLDivElement>(null);
+  const [expanded, setExpanded] = useState(false);
+  const [visibleCount, setVisibleCount] = useState(2);
+
+  useLayoutEffect(() => {
+    const grid = gridRef.current;
+    if (!grid) return;
+
+    const measure = () => {
+      const width = grid.getBoundingClientRect().width || grid.clientWidth;
+      const columns = Math.max(
+        1,
+        Math.floor((width + GRID_GAP) / (MIN_FILE_WIDTH + GRID_GAP)),
+      );
+      setVisibleCount(columns * 2);
+    };
+    measure();
+
+    if (typeof ResizeObserver === "undefined") {
+      window.addEventListener("resize", measure);
+      return () => window.removeEventListener("resize", measure);
+    }
+    const observer = new ResizeObserver(measure);
+    observer.observe(grid);
+    return () => observer.disconnect();
+  }, [artifacts.length]);
+
+  if (artifacts.length === 0) return null;
+
+  const hasOverflow = artifacts.length > visibleCount;
+  const hiddenCount = Math.max(0, artifacts.length - visibleCount);
+  const visibleArtifacts = expanded
+    ? artifacts
+    : artifacts.slice(0, visibleCount);
+
+  return (
+    <div className={styles.list} data-testid="response-artifacts">
+      <div ref={gridRef} className={styles.grid}>
+        {visibleArtifacts.map((artifact) => {
+          const change = artifactChange(artifact.toolName);
+          return (
+            <button
+              key={artifact.id}
+              type="button"
+              className={styles.file}
+              title={artifact.path}
+              aria-label={`${artifact.name} ${artifact.path}`}
+              onClick={(event) => {
+                event.preventDefault();
+                event.stopPropagation();
+                window.dispatchEvent(
+                  new CustomEvent("qwenpaw:open-file-preview", {
+                    detail: {
+                      target: artifact.target,
+                      trigger: event.currentTarget,
+                    },
+                  }),
+                );
+              }}
+            >
+              <span className={styles.icon}>
+                <FileGlyph name={artifact.name} size={20} />
+              </span>
+              <span className={styles.details}>
+                <strong>{artifact.name}</strong>
+                <small title={artifact.path}>{artifact.path}</small>
+              </span>
+              <span className={styles.status} data-change={change}>
+                {t(
+                  change === "created"
+                    ? "files.artifactCreated"
+                    : "files.artifactModified",
+                )}
+              </span>
+            </button>
+          );
+        })}
+      </div>
+      {hasOverflow && (
+        <button
+          type="button"
+          className={styles.toggle}
+          aria-expanded={expanded}
+          onClick={() => setExpanded((current) => !current)}
+        >
+          {expanded ? (
+            <>
+              {t("files.artifactsCollapse")}
+              <ChevronUp size={14} />
+            </>
+          ) : (
+            <>
+              {t("files.artifactsExpand", { count: hiddenCount })}
+              <ChevronDown size={14} />
+            </>
+          )}
+        </button>
+      )}
+    </div>
+  );
+}
